begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('abc00000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'team-'||i||'@test.invalid','{"display_name":"Team Fixture"}'::jsonb from generate_series(1,5) i;
insert into public.staff_accounts(id,email,display_name) select id,email,'Team Fixture' from auth.users where email like 'team-%@test.invalid';
insert into public.staff_roles values
 ('abc00000-0000-4000-8000-000000000001','organizer'),('abc00000-0000-4000-8000-000000000002','main_judge'),('abc00000-0000-4000-8000-000000000003','trainer'),('abc00000-0000-4000-8000-000000000004','trainer'),('abc00000-0000-4000-8000-000000000005','line_judge');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_team('abc10000-0000-4000-8000-000000000001','Club A','Almaty')$$,'organizer creates club');
select lives_ok($$select public.save_team('abc10000-0000-4000-8000-000000000002','Club B','Astana')$$,'organizer creates second club');
select is((select count(*)::int from public.subteams where team_id='abc10000-0000-4000-8000-000000000001'),3,'three age-group subteams created atomically');
select lives_ok($$select public.save_season('abc20000-0000-4000-8000-000000000001','Roster Season',2026,'2026-01-01','2026-12-31')$$,'season fixture');
select lives_ok($$select public.register_season_team('abc20000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000001')$$,'club registers in season');
select lives_ok($$select public.register_season_team('abc20000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000002')$$,'receiving club registers');
select lives_ok($$select public.assign_team_trainer('abc00000-0000-4000-8000-000000000003','abc10000-0000-4000-8000-000000000001',array(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'))$$,'trainer assigned within parent club');
select throws_ok($$select public.assign_team_trainer('abc00000-0000-4000-8000-000000000003','abc10000-0000-4000-8000-000000000001',array(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000002'))$$,'22023','Subteams must belong to the club','cross-club subteam assignment rejected');
select throws_ok($$select public.assign_team_trainer('abc00000-0000-4000-8000-000000000005','abc10000-0000-4000-8000-000000000001',array(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001'))$$,'22023','Active Trainer required','line judge cannot receive trainer scope');
select lives_ok($$select public.assign_team_trainer('abc00000-0000-4000-8000-000000000004','abc10000-0000-4000-8000-000000000002',array(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000002'))$$,'second trainer assigned another club');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from public.teams where id in('abc10000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000002')),1,'trainer sees only own club');
select is((select count(*)::int from public.available_team_trainers()),1,'trainer name lookup remains club-scoped');
select lives_ok($$select public.save_team('abc10000-0000-4000-8000-000000000001','Club A Edited','Almaty')$$,'trainer edits own club');
select throws_ok($$select public.save_team('abc10000-0000-4000-8000-000000000002','Stolen Club','Almaty')$$,'42501','Team permission required','trainer cannot edit other club');
select throws_ok($$select public.save_team(gen_random_uuid(),'New Club','Almaty')$$,'42501','Team permission required','trainer cannot create another club');
select throws_ok($$select public.assign_team_trainer(auth.uid(),'abc10000-0000-4000-8000-000000000002',array[]::uuid[])$$,'42501','Team permission required','trainer cannot grant own club scope');
select lives_ok($$select public.save_player('abc30000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000001','Young','Player','boy','2014-06-15','right','attack','junior',null)$$,'trainer creates player without Auth account');
select is((select current_rating from public.players where id='abc30000-0000-4000-8000-000000000001'),1000::numeric,'new player initial rating 1000');
select is((select count(*)::int from public.rating_history where player_id='abc30000-0000-4000-8000-000000000001' and source='initial'),1,'initial rating provenance recorded');
select lives_ok($$select public.save_player('abc30000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000001','Young','Edited','boy','2014-06-15','left','defence','junior',null)$$,'player attributes editable');
select is((select count(*)::int from public.rating_history where player_id='abc30000-0000-4000-8000-000000000001'),1,'editing player does not duplicate/reset rating');
select throws_ok($$select public.save_player(gen_random_uuid(),'abc10000-0000-4000-8000-000000000002','Other','Player','girl','2014-01-01','right','attack','junior',null)$$,'42501','Team permission required','trainer cannot create player in other club');
select lives_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),'abc30000-0000-4000-8000-000000000001')$$,'eligible player joins own subteam');
select lives_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),'abc30000-0000-4000-8000-000000000001')$$,'duplicate add is idempotent');
select is((select count(*)::int from public.roster_memberships where player_id='abc30000-0000-4000-8000-000000000001'),1,'duplicate did not add history');
select throws_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U15'),'abc30000-0000-4000-8000-000000000001')$$,'42501','Subteam permission required','trainer cannot manage unassigned subteam');
select throws_ok($$select public.save_player('abc30000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000001','Young','Player','boy','2011-06-15','right','attack','junior',null)$$,'22023','DOB invalidates an active roster','DOB edit cannot bypass roster age');
select lives_ok($$select public.set_player_trainer('abc30000-0000-4000-8000-000000000001','first',null,'First','Coach')$$,'free trainer name accepted');
select lives_ok($$select public.set_player_trainer('abc30000-0000-4000-8000-000000000001','personal','abc00000-0000-4000-8000-000000000003',null,null)$$,'linked trainer accepted');
select throws_ok($$select public.set_player_trainer('abc30000-0000-4000-8000-000000000001','personal','abc00000-0000-4000-8000-000000000003','Mixed','Coach')$$,'22023','Active linked trainer or free name required','linked and free names mutually exclusive');
select lives_ok($$select public.set_player_trainer_reference('abc30000-0000-4000-8000-000000000001','first','{"trainer_id":null,"first_name":"Free","last_name":"Coach"}')$$,'JSON wrapper preserves explicit null trainer');
select throws_ok($$select public.set_player_trainer('abc30000-0000-4000-8000-000000000001','first',null,null,null)$$,'23514',null,'missing free name rejected');
select throws_ok($$update public.players set current_rating=9999$$,'42501',null,'direct rating forgery denied');
select throws_ok($$insert into public.roster_memberships(season_id,subteam_id,player_id) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'42501',null,'direct roster bypass denied');
select throws_ok($$delete from public.rating_history$$,'42501',null,'rating history immutable');
select throws_ok($$select public.transfer_player('abc30000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000002','Move')$$,'42501','Organizer required','trainer cannot transfer player');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U15'),'abc30000-0000-4000-8000-000000000001')$$,'22023','Age group mismatch','playing up forbidden even for Organizer');
select throws_ok($$select public.save_season('abc20000-0000-4000-8000-000000000001','Roster Season',2027,'2026-01-01','2026-12-31')$$,'22023','Year invalidates an active roster','season year cannot invalidate assigned ages');
reset role;
insert into public.players(id,team_id,first_name,last_name,gender,date_of_birth,playing_hand,playing_style,sports_level) select md5('capacity-'||i)::uuid,'abc10000-0000-4000-8000-000000000001','Capacity',i::text,'boy','2014-01-01','right','attack','junior' from generate_series(2,11)i;
set local role authenticated;
select lives_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),md5('capacity-'||i)::uuid) from generate_series(2,10)i$$,'ten-player roster has no gender quota');
select throws_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),md5('capacity-11')::uuid)$$,'22023','Roster capacity reached','eleventh active player denied');
select throws_ok($$select public.drop_player('abc30000-0000-4000-8000-000000000001','2010-01-01','Before birth')$$,'22023','Date and reason required','dropout cannot predate birth');
select lives_ok($$select public.drop_player('abc30000-0000-4000-8000-000000000001',current_date,'Injury')$$,'dropout records date/reason');
select is((select count(*)::int from public.player_status_events where player_id='abc30000-0000-4000-8000-000000000001'),1,'dropout event retained');
select is((select count(*)::int from public.roster_memberships where player_id='abc30000-0000-4000-8000-000000000001' and ended_at is not null),1,'dropout ends rather than deletes membership');
select is((select count(*)::int from public.rating_history where player_id='abc30000-0000-4000-8000-000000000001'),1,'dropout preserves rating history');
select throws_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),'abc30000-0000-4000-8000-000000000001')$$,'22023','Eligible active club player required','dropped player cannot rejoin a roster');
select lives_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000001' and age_group='U13'),md5('capacity-11')::uuid)$$,'dropout frees capacity');
select lives_ok($$select public.transfer_player(md5('capacity-2')::uuid,'abc10000-0000-4000-8000-000000000002','Approved mid-season move')$$,'Organizer approves transfer');
select is((select count(*)::int from public.roster_memberships where player_id=md5('capacity-2')::uuid and ended_at is not null),1,'transfer preserves ended prior membership');
select lives_ok($$select public.add_roster_player('abc20000-0000-4000-8000-000000000001',(select id from public.subteams where team_id='abc10000-0000-4000-8000-000000000002' and age_group='U13'),md5('capacity-2')::uuid)$$,'receiving club can select transferred player');
select is((select count(*)::int from public.roster_memberships where player_id=md5('capacity-2')::uuid),2,'both memberships retained');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from public.players where id=md5('capacity-2')::uuid),0,'former trainer cannot read transferred private DOB');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*)::int from public.players where id=md5('capacity-2')::uuid),1,'receiving trainer sees current private player');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.teams where id in('abc10000-0000-4000-8000-000000000001','abc10000-0000-4000-8000-000000000002')),2,'Main Judge manages both clubs');
select throws_ok($$select public.transfer_player(md5('capacity-2')::uuid,'abc10000-0000-4000-8000-000000000001','Unapproved')$$,'42501','Organizer required','Main Judge cannot approve transfer');
select set_config('request.jwt.claims','{"sub":"abc00000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select is((select count(*)::int from public.players),0,'Line Judge has no roster/DOB access');
select is((select count(*)::int from public.available_team_trainers()),0,'Line Judge cannot use private trainer lookup');
select throws_ok($$select public.drop_player(md5('capacity-2')::uuid,current_date,'Unauthorized')$$,'42501','Team permission required','Line Judge cannot drop player');
set local role anon;
select throws_ok($$select * from public.players$$,'42501',null,'anonymous private player access denied');
select throws_ok($$select * from public.player_status_events$$,'42501',null,'anonymous dropout reasons denied');
select throws_ok($$select * from public.player_trainer_refs$$,'42501',null,'anonymous trainer references denied');
select throws_ok($$select * from public.roster_memberships$$,'42501',null,'anonymous base roster denied');
select throws_ok($$select public.save_team(gen_random_uuid(),'Public Club','Almaty')$$,'42501',null,'anonymous club writes denied');
select * from finish();
rollback;
